arguments.script:
// Attack 1: a head's biome.json extends /proc/<pid>/environ, so Biome's parse error quotes the round's logins. The
// round comment must not carry a check's error out of the job.
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const secret = "MELIAN_CODEX_ACCESS_TOKEN=probe-secret-4f2a9c";
const base = "a".repeat(40);
const head = "b".repeat(40);
const dir = mkdtempSync(join(tmpdir(), "round-"));
const verdict = {
	status: "not-reviewed",
	blocking: false,
	findings: { block: [], acknowledge: [] },
	ran: [],
	notRun: [
		{
			name: "static.biome",
			status: "toolFailed",
			error: `biome.json extends /proc/4242/environ, which could not be parsed: unexpected character at 1:1: ${secret}\0PATH=/usr/bin`,
		},
	],
};
writeFileSync(join(dir, "verdict.json"), JSON.stringify(verdict));
writeFileSync(join(dir, "rounds.json"), JSON.stringify([{ base, head }]));
const args = ["scripts/round-comment.mjs", "--verdict", join(dir, "verdict.json"), "--rounds", join(dir, "rounds.json")];
args.push("--exit", "2", "--run-url", "https://example.invalid/run/1", "--run-id", "1", "--nonce", "0".repeat(32));
args.push("--base", base, "--head", head, "--merge-base", base, "--current-base", base, "--current-head", head);
const run = spawnSync(process.execPath, args, { encoding: "utf8" });
console.log(`exit ${run.status}\n${run.stdout}${run.stderr}`);
if (run.status !== 0) process.exit(2);
process.exit(run.stdout.includes("probe-secret-4f2a9c") ? 1 : 0);
